import{Z as t,e as n,f as s,a0 as a}from"./chunks/framework.DmpHOl9T.js";const m=JSON.parse('{"title":"Stencils","description":"","frontmatter":{},"headers":[],"relativePath":"forms/stencils.md","filePath":"forms/stencils.md","lastUpdated":1782532814000}'),i={name:"forms/stencils.md"};function o(r,e,l,c,d,h){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="stencils" tabindex="-1">Stencils <a class="header-anchor" href="#stencils" aria-label="Permalink to &quot;Stencils&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For team rollout and project-stencil patterns, see <a href="/guides/control-panel-admin/stencils-for-repeatable-form-types">Stencils for repeatable form types</a>.</p></div><p>Stencils are reusable starter forms.</p><p>They are useful when you want a faster, more consistent starting point than building every new form from scratch. A stencil can carry the same kinds of structure and setup you would normally define on a form, including fields and layout, pages, notifications, and form settings.</p><p>That means a stencil is more than a visual starting point. It can carry real behaviour with it as well.</p><h2 id="when-to-use-stencils" tabindex="-1">When to Use Stencils <a class="header-anchor" href="#when-to-use-stencils" aria-label="Permalink to &quot;When to Use Stencils&quot;">​</a></h2><p>Stencils are especially helpful when:</p><ul><li>a team creates the same kinds of forms repeatedly</li><li>clients need a safe starting point</li><li>you want to keep common patterns consistent across projects</li></ul><p>Formie includes a default <code>Contact Form</code> stencil as a general starting point, and you can create your own when you need something more specific.</p><h2 id="creating-and-using-stencils" tabindex="-1">Creating and Using Stencils <a class="header-anchor" href="#creating-and-using-stencils" aria-label="Permalink to &quot;Creating and Using Stencils&quot;">​</a></h2><p>Create and manage stencils under <strong>Formie → Stencils</strong> (requires the <strong>Access stencils</strong> permission). Building a stencil works much like building a normal form, so you can define the layout, notifications, and form settings you want to reuse.</p><p>Choose <strong>New stencil</strong> to create one you can edit in the control panel. Once a stencil exists, it becomes an option when creating a new form. Choosing a stencil gives you a quick starting point, and from there the form becomes its own form that can be changed independently.</p><p>Saving a form as a stencil from the form builder creates a new stencil you can edit later.</p><h3 id="synced-fields" tabindex="-1">Synced Fields <a class="header-anchor" href="#synced-fields" aria-label="Permalink to &quot;Synced Fields&quot;">​</a></h3><p>Stencils can include <strong>synced fields</strong>—the same shared field definitions you use across forms.</p><p>When you add an existing field as a synced field while building a stencil, Formie remembers that link in the stencil snapshot. Creating a new form from that stencil adds a new placement that points at the same shared definition, so your site-wide email, consent, or other shared fields stay consistent.</p><p>If a shared definition cannot be found on the current environment (for example, a project stencil references a handle that does not exist yet), Formie falls back to creating an independent field copy from the stencil settings.</p><h2 id="shared-starting-points" tabindex="-1">Shared Starting Points <a class="header-anchor" href="#shared-starting-points" aria-label="Permalink to &quot;Shared Starting Points&quot;">​</a></h2><p>Stencils are best treated as starting templates, not shared live forms. Changes made to a stencil affect future forms created from it, not forms that already exist.</p><h2 id="project-stencils-developers" tabindex="-1">Project Stencils (Developers) <a class="header-anchor" href="#project-stencils-developers" aria-label="Permalink to &quot;Project Stencils (Developers)&quot;">​</a></h2><p>Some stencils are created as <strong>project stencils</strong> and stored in project config (<code>formie.stencils</code>). They are useful for starter kits and defaults that should be versioned with the site and shared across a team.</p><p>Handles must be unique across both regular and project stencils.</p><p>On sites where admin changes are disabled, project stencils are <strong>view-only</strong> in the control panel. You can still open them and use <strong>Save a copy</strong> to create an editable stencil of your own.</p><ul><li><strong>New stencil</strong> — available to everyone with stencil access.</li><li><strong>New project stencil</strong> — only when admin changes are enabled (typically local or staging).</li></ul>',24)])])}const u=t(i,[["render",o]]);export{m as __pageData,u as default};
